import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

// 模拟传感器：这是一个「冷流」，只有被 collect 时才会真正开始工作
class TemperatureSensor(private val name: String) {
    fun readings(): Flow<Double> = flow {
        println("[$name] 开始采集（说明上游被真正执行了）")
        var temp = 20.0
        while (true) {
            emit(temp)                 // 产出一个读数
            delay(200)                 // 每 200ms 产生一次
            temp += (Math.random() - 0.5) * 2
        }
    }
}

fun main() = runBlocking {
    val sensor = TemperatureSensor("室外")

    // ---------- 1. 冷流：两个收集者 = 两次独立采集 ----------
    println("== 冷流演示 ==")
    val cold: Flow<Double> = sensor.readings().take(2)
    cold.collect { println("收集者A: %.2f".format(it)) }
    cold.collect { println("收集者B: %.2f".format(it)) }   // 上游再次执行！

    // ---------- 2. shareIn：转成热流，多订阅者共享一次上游 ----------
    val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())

    val shared: SharedFlow<String> = sensor.readings()
        .map { "温度 %.2f ℃".format(it) }
        .shareIn(
            scope,
            started = SharingStarted.WhileSubscribed(stopTimeoutMillis = 1000),
            replay = 1                    // 新订阅者立刻拿到最近 1 个值
        )

    val job1 = launch { shared.take(3).collect { println("订阅者1 <- $it") } }
    val job2 = launch { shared.take(3).collect { println("订阅者2 <- $it") } }
    joinAll(job1, job2)

    // ---------- 3. stateIn：压缩成「当前值」，适合 UI 状态 ----------
    val uiState: StateFlow<String> = sensor.readings()
        .map { if (it > 20.5) "⚠ 高温报警" else "✅ 正常" }
        .distinctUntilChanged()          // 状态没变就不重复通知
        .stateIn(scope, SharingStarted.WhileSubscribed(1000), "初始化中...")

    delay(500)
    println("UI 当前状态: ${uiState.value}")   // StateFlow 可同步读取 value

    // ---------- 4. combine：并行合并多个流 ----------
    val humidity = flow {
        emit(40); delay(150); emit(55); delay(150); emit(62)
    }
    combine(sensor.readings().take(3), humidity) { t, h ->
        "温度=%.1f℃, 湿度=%d%%".format(t, h)
    }.collect { println("环境面板: $it") }

    scope.cancel()   // 记得取消作用域，否则热流会一直跑
}

